import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"URI 协议（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/uri-protocol.md","filePath":"zh-CN/user-guide/uri-protocol.md","lastUpdated":1787586465000}'),l={name:"zh-CN/user-guide/uri-protocol.md"};function i(o,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="uri-协议-lertaro" tabindex="-1">URI 协议（lertaro://） <a class="header-anchor" href="#uri-协议-lertaro" aria-label="Permalink to &quot;URI 协议（lertaro://）&quot;">​</a></h1><p>Lertaro 在首次运行时会自动在 Windows 系统中注册自定义协议 <strong><code>lertaro://</code></strong>。无论是网页超链接、桌面快捷方式、自动化脚本还是第三方软件，均可通过该协议直接唤起 Lertaro 的特定搜索、直达设置页面或发起跨设备传输。</p><h2 id="_1-协议机制与实例路由" tabindex="-1">1. 协议机制与实例路由 <a class="header-anchor" href="#_1-协议机制与实例路由" aria-label="Permalink to &quot;1. 协议机制与实例路由&quot;">​</a></h2><ul><li><strong>开箱即用</strong>：无需手动配置注册表，Lertaro 启动时会自动完成注册与自愈校验。</li><li><strong>单实例路由</strong>：若 Lertaro 已经在后台运行，打开 <code>lertaro://</code> 链接会直接唤醒当前运行中的前台实例，绝不会重复启动多个进程；若 Lertaro 尚未启动，系统会自动拉起主程序并立即执行链接指定的动作。</li></ul><h2 id="_2-完整-uri-路由指令表" tabindex="-1">2. 完整 URI 路由指令表 <a class="header-anchor" href="#_2-完整-uri-路由指令表" aria-label="Permalink to &quot;2. 完整 URI 路由指令表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">URI 指令格式</th><th style="text-align:left;">功能说明与交互效果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">激活并显示快速搜索窗口（效果等同于双击 <code>Ctrl</code> 全局热键）。</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[关键词]</code></td><td style="text-align:left;">激活快速搜索窗口，并预先填入指定的 <code>[关键词]</code> 并立即过滤。</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[关键词]</code></td><td style="text-align:left;">打开大尺寸完整搜索主窗口，并预先填入指定的 <code>[关键词]</code>。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[分区]</code></td><td style="text-align:left;">打开设置窗口，并直接切换到指定的顶层分区标签页。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[序号]</code></td><td style="text-align:left;">打开设置窗口并精准跳转到某一项具体设置项，同时闪烁高亮该选项。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">打开空白的 LocalSend 局域网发送窗口。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[编码后的绝对路径...]</code></td><td style="text-align:left;">打开 LocalSend 并切换至文件模式，自动添加一个或多个目标文件/目录。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[编码后的文本]</code></td><td style="text-align:left;">打开 LocalSend 并切换至文本模式，自动填入指定的待发送文本。</td></tr></tbody></table><h3 id="设置分区参数-分区" tabindex="-1">设置分区参数 <code>[分区]</code> <a class="header-anchor" href="#设置分区参数-分区" aria-label="Permalink to &quot;设置分区参数 \`[分区]\`&quot;">​</a></h3><p>设置分区参数不区分大小写，对应设置界面的侧边栏模块：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - 运行状态</span></span>
<span class="line"><span>Index        - 索引设置</span></span>
<span class="line"><span>General      - 通用设置</span></span>
<span class="line"><span>Appearance   - 外观与主题</span></span>
<span class="line"><span>Hotkeys      - 热键设置</span></span>
<span class="line"><span>Plugins      - 插件管理</span></span>
<span class="line"><span>Favorites    - 收藏夹</span></span>
<span class="line"><span>History      - 历史记录</span></span>
<span class="line"><span>QuickPanel   - 快速面板</span></span>
<span class="line"><span>About        - 关于与更新</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>lertaro://settings/entry/[序号]</code> 中的序号是由内置的<a href="./instant-answers.html#2-关键词触发功能内置插件"><strong>设置搜索</strong></a>功能动态生成的。由于内部序号在版本更新或重启后可能会重新分配，建议在外部脚本中优先使用 <code>lertaro://settings/page/[分区]</code>。</p></div><h2 id="_3-localsend-路由与参数编码规范" tabindex="-1">3. LocalSend 路由与参数编码规范 <a class="header-anchor" href="#_3-localsend-路由与参数编码规范" aria-label="Permalink to &quot;3. LocalSend 路由与参数编码规范&quot;">​</a></h2><p>在使用 LocalSend 相关 URI 时，每个文件路径或文本必须进行标准的 URL 编码（例如将 <code>:</code> 转换为 <code>%3A</code>，将 <code>\\</code> 转换为 <code>%5C</code>，将空格转换为 <code>%20</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 预填多个文件路径</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 预填待发送文本</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>安全约束</strong>：所有传入的文件路径必须为本机已经真实存在的绝对路径；带有预填内容的链接仅会打开 LocalSend 并进入设备选择界面，绝不会自动向任何设备发送数据。</li></ul><h2 id="_4-外部联动实战示例" tabindex="-1">4. 外部联动实战示例 <a class="header-anchor" href="#_4-外部联动实战示例" aria-label="Permalink to &quot;4. 外部联动实战示例&quot;">​</a></h2><h3 id="浏览器与-markdown-链接" tabindex="-1">浏览器与 Markdown 链接 <a class="header-anchor" href="#浏览器与-markdown-链接" aria-label="Permalink to &quot;浏览器与 Markdown 链接&quot;">​</a></h3><p>在个人知识库（如 Obsidian、Notion 或 Markdown 文档）中直接插入超链接：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">点击打开 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Lertaro 外观设置</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">点击快速查找 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">项目财务报表</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/财务报表%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="windows-快捷方式与批处理" tabindex="-1">Windows 快捷方式与批处理 <a class="header-anchor" href="#windows-快捷方式与批处理" aria-label="Permalink to &quot;Windows 快捷方式与批处理&quot;">​</a></h3><p>在桌面右键新建快捷方式，在对象位置输入：</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>在 PowerShell 脚本中调用：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-安全性与未知路由容错" tabindex="-1">5. 安全性与未知路由容错 <a class="header-anchor" href="#_5-安全性与未知路由容错" aria-label="Permalink to &quot;5. 安全性与未知路由容错&quot;">​</a></h2><ul><li><strong>静默容错</strong>：由于任何外部网页或脚本均可尝试触发该协议，Lertaro 对所有传入的 URI 实行严格的白名单校验。若链接格式错误、拼写有误或指向不存在的路由，Lertaro 会直接安全忽略，仅记录调试日志，绝不会产生意外的破坏性操作或崩溃。</li></ul>`,25)])])}const k=a(l,[["render",i]]);export{g as __pageData,k as default};
